use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    // index 0 = least recently used, end = most recent
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    keys.remove(i)
                    vals.remove(i)
                } else {
                    i += 1
                }
            }
            keys.push(k)
            vals.push(v)
            if keys.len() as int > cap {
                let e = keys.remove(0)
                vals.remove(0)
                println("evict ${e}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    found = vals[i]
                    keys.remove(i)
                    vals.remove(i)
                    keys.push(k)
                    vals.push(found)
                    break
                }
                i += 1
            }
            println("${found}")
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = keys.len()
                while i > 0 {
                    i -= 1
                    if out != "" {
                        out = out + " "
                    }
                    out = out + "${keys[i]}"
                }
                println("${out}")
            }
        }
    }
}

